bug_report:
[15 Regression] too early coroutine destruction of co_await on nix-2.24.8
Initially observed the failure as a SIGSEGV on a nix-2.24.8 testsuite. The test runs on gcc-14 and fails on gcc-15 fromr15-3941-g2531f014fb2364.

I think I managed to convert it to a build failure that complains about use of a destroyed object:

// $ substitution-goal.cc
#include <coroutine>

struct promise_type;
using handle_type = std::coroutine_handle<promise_type>;

struct Co {
    handle_type handle;
    using promise_type = ::promise_type;

    explicit Co(handle_type handle) : handle(handle) {}

    bool await_ready() { return false; }
    std::coroutine_handle<> await_suspend(handle_type handle);
    void await_resume() {}
};

struct Done {};

struct promise_type {
    Co get_return_object();

    std::suspend_always initial_suspend() { return {}; };
    std::suspend_always final_suspend() noexcept { return {}; };
    void return_value(Done) {}
    void return_value(Co&&);
    void unhandled_exception() { throw; };
    Co&& await_transform(Co&& co) { return static_cast<Co&&>(co); }
};

Co tryToRun();

Co init()
{
    co_await tryToRun();
    co_return Done{};
}

Good gcc-14:

$ g++-14 -o bug.o -c substitution-goal.cc -std=c++2a -Werror=dangling-pointer -Wall

Bad gcc-15:

